mod native_field_metadata { use aa_rules::native::{Error,Result}; use std::collections::BTreeSet;
fn hash(name:&str)->u32{name.bytes().fold(0u32,|h,b|h.wrapping_mul(33).wrapping_add(u32::from(b.to_ascii_uppercase())))}
fn indices(names:&[&str])->Result<Vec<usize>>{
 let mut seen=BTreeSet::new();let mut buckets=vec![Vec::<usize>::new();5];
 for(index,name)in names.iter().enumerate(){
  if name.is_empty()||!name.is_ascii()||name.bytes().any(|b|!b.is_ascii_alphanumeric()&&b!=b'_'){
   return Err(Error::Unsupported("fresh SVar field hash requires an ASCII identifier".into()))
  }
  if !seen.insert(name.to_ascii_lowercase()){return Err(Error::Unsupported(format!("fresh SVar node repeats field {name}")))}
  if index>=buckets.len().checked_mul(2).ok_or_else(||Error::Unsupported("SVar field table size overflow".into()))?{
   let mut size=buckets.len().checked_mul(2).and_then(|v|v.checked_add(1)).ok_or_else(||Error::Unsupported("SVar field table size overflow".into()))?;
   while size%3==0||size%5==0{size=size.checked_add(2).ok_or_else(||Error::Unsupported("SVar field table growth overflow".into()))?;}
   let mut next=vec![Vec::new();size];
   for chain in buckets{for prior in chain{next[hash(names[prior])as usize%size].insert(0,prior)}}
   buckets=next;
  }
  let slot=hash(name)as usize%buckets.len();buckets[slot].insert(0,index);
 }
 Ok(buckets.into_iter().flatten().collect())
}
pub fn native_fresh_field_order(names:&[&str])->Result<Vec<usize>>{indices(names)}

}
mod settings { pub use aa_runtime::settings::{Settings,Declaration,Error,Result};
use std::collections::BTreeMap;
use aa_rules::{resources::Provenance,sources::{ResolvedFile,V14Sources},tgi::{Document,Item,Limits}};
pub const APP_VARIABLE_FILES: [&str; 5] = [
    "AVars.tgi",
    "AVars_AA.tgi",
    "AVars_ClientCadence.tgi",
    "AVars_Locale.tgi",
    "AVars_version.tgi",
];
pub fn load_current_v14(sources: &mut V14Sources, limits: Limits) -> Result<Settings> {
    let mut out = Settings::from_files(
        [
            sources.read("Game/SVars.tgi")?,
            sources.read("Game/SVars_AA.tgi")?,
        ],
        limits,
    )?;
    for path in APP_VARIABLE_FILES {
        collect(sources.read(path)?, "Vars", limits, &mut out.app_variables)?;
    }
    Ok(out)
}
fn collect(
    file: ResolvedFile,
    node_name: &str,
    limits: Limits,
    out: &mut BTreeMap<String, Vec<Declaration>>,
) -> Result<()> {
    if aa_rules::sources::sha256(&file.bytes) != file.sha256 {
        return Err(Error::Field(
            file.logical_path,
            "source SHA256 differs from bytes".into(),
        ));
    }
    let doc = Document::parse_native(file.bytes, limits)?;
    for item in &doc.items {
        let Item::Node(node) = item else { continue };
        if !doc
            .header_name(&node.header)
            .is_some_and(|s| s.eq_ignore_ascii_case(node_name))
        {
            continue;
        }
        for item in &node.items {
            let Item::Property(p) = item else { continue };
            let Some(name) = doc.property_name(p) else {
                continue;
            };
            let Some(raw) = doc.property_value(p) else {
                continue;
            };
            if !(1..=2).contains(&p.left.len()) {
                return Err(Error::Field(
                    name.into(),
                    "unsupported declaration tokens".into(),
                ));
            }
            let field_type = if p.left.len() == 2 {
                Some(
                    doc.text(p.left[0].span)
                        .ok_or_else(|| {
                            Error::Field(name.into(), "invalid field type text".into())
                        })?
                        .to_owned(),
                )
            } else {
                None
            };
            out
                .entry(name.to_ascii_lowercase())
                .or_default()
                .push(Declaration {
                    field_type,
                    raw: raw.into(),
                    source: Provenance {
                        path: file.logical_path.clone(),
                        sha256: file.sha256.clone(),
                        span: p.span,
                    },
                });
        }
    }
    Ok(())
}

}

pub use aa_runtime::combat_source_completion;

fn main(){
use aa_rules::{actors::ActorCatalog,sources::{V14Sources,SourceLimits},tgi::Limits};
use crate::{catalog::Catalog,combat_source_receipt::VerifiedStartupReceipt,load_view_variables::NativeOverrides,view_startup_inputs::Inputs};
    let game = std::path::PathBuf::from(std::env::var_os("AA_GAME_ROOT").expect("AA_GAME_ROOT"));
    let mut files = V14Sources::open(
        game.join("Data.rwd"),
        game.join("reconstruction/native-game/runtime-expanded-v14"),
        SourceLimits {
            max_member_bytes: u64::MAX,
        },
    )
    .unwrap();
    let actors = ActorCatalog::load_v14(&mut files).unwrap();
    let mut catalog = Catalog::new(&actors);
    catalog.settings =
        Some(crate::settings::load_current_v14(&mut files, Limits::default()).unwrap());
    let receipt = VerifiedStartupReceipt::verify_embedded_reference(&catalog, &mut files).unwrap();
    let early = Inputs::from_fresh_sources(
        &catalog,
        &receipt,
        &mut files,
        NativeOverrides::ControlledNone,
    )
    .err()
    .unwrap();
    assert!(early.seeds().is_none() && early.grid().is_none() && early.orientation().is_none());
    assert!(early.camera().is_none() && early.aliases().is_none());
    crate::combat_source_completion::install(
        &catalog,
        &mut files,
        receipt.context(),
        receipt.csv(),
        receipt.globals(),
    )
    .unwrap();
    crate::combat_source_completion::compute(&catalog).unwrap();

    //Reject the second reached public/private binding after preserving the
    //first source write TerrainBlockSize=8 in the same partial owner.
    let declaration = &mut catalog
        .settings
        .as_mut()
        .unwrap()
        .app_variables
        .get_mut("vgridcellsize")
        .unwrap()[0];
    let original = std::mem::replace(&mut declaration.raw, "9".into());
    let partial = Inputs::from_fresh_sources(
        &catalog,
        &receipt,
        &mut files,
        NativeOverrides::ControlledNone,
    )
    .err()
    .unwrap();
    assert!(partial.seeds().is_some());
    let grid = partial.grid().expect("same partial source owner");
    assert_eq!(grid.terrain_block_size(), 8);
    assert!(grid.validate(&catalog).unwrap_err().contains("incomplete"));
    assert!(partial.orientation().is_none());
    assert!(partial.camera().is_none() && partial.aliases().is_none());
    catalog
        .settings
        .as_mut()
        .unwrap()
        .app_variables
        .get_mut("vgridcellsize")
        .unwrap()[0]
        .raw = original;

    let alias_key = crate::view_init_assets::alias_keys()
        .next()
        .unwrap()
        .to_ascii_lowercase();
    let raw = &mut catalog
        .settings
        .as_mut()
        .unwrap()
        .app_variables
        .get_mut(&alias_key)
        .unwrap()[0]
        .raw;
    let original_alias = std::mem::replace(raw, "__projection_differs__".into());
    let late = Inputs::from_fresh_sources(
        &catalog,
        &receipt,
        &mut files,
        NativeOverrides::ControlledNone,
    )
    .err()
    .unwrap();
    assert!(
        late.seeds().is_some()
            && late.grid().is_some()
            && late.orientation().is_some()
            && late.camera().is_some()
    );
    assert!(
        late.aliases()
            .unwrap()
            .validate_in_bank(&catalog, &catalog.definition_bank.borrow())
            .unwrap_err()
            .contains("incomplete")
    );
    catalog
        .settings
        .as_mut()
        .unwrap()
        .app_variables
        .get_mut(&alias_key)
        .unwrap()[0]
        .raw = original_alias;

    let inputs = Inputs::from_fresh_sources(
        &catalog,
        &receipt,
        &mut files,
        NativeOverrides::ControlledNone,
    )
    .unwrap();
    let bank = catalog.definition_bank.borrow();
    inputs.validate(&catalog, &bank).unwrap();
    assert_eq!(
        (
            inputs.grid().terrain_block_size(),
            inputs.grid().vgrid_cell_size()
        ),
        (8, 4)
    );
    assert_eq!(
        inputs.orientation().current(&catalog, &bank).unwrap(),
        [0, 0xbf800000, 0]
    );
    assert_eq!(
        inputs.camera().word(&catalog, &bank, 0x40).unwrap(),
        2.1f32.to_bits()
    );
    for key in crate::view_init_assets::alias_keys().chain(["TextureEnvironmentMap"]) {
        assert!(
            !inputs
                .aliases()
                .alias_410cb0(&catalog, &bank, key)
                .unwrap()
                .units()
                .is_empty()
        );
    }
    let mut globals = inputs.seeds().bind(&catalog).unwrap();
    let grid = crate::view_grid_state::State::<usize>::from_constructor(&mut globals).unwrap();
    assert_eq!(grid.word(0x14).unwrap(), Some(0));
    assert_eq!(grid.word(0x28).unwrap(), None);
    drop(bank);


println!("PASS: actual five-owner Inputs factory and early/Grid/late-Alias retained failure prefixes; camera v14zoom/current aliases verified; no Application-install, VWorld or battle execution");
}
